const rarityOrder=["Common","Rare","Elite","Mythic","Special","Unobtainable"];
const board=document.querySelector("#tierBoard");
const modal=document.querySelector("#standModal");
const modalImage=document.querySelector("#modalImage");
const modalName=document.querySelector("#modalName");
const modalRarity=document.querySelector("#modalRarity");
const modalDescription=document.querySelector("#modalDescription");
const closeModal=document.querySelector("#closeModal");

function createCard(stand){
    const card=document.createElement("button");
    card.className=`stand-card rarity-${stand.rarity.toLowerCase()}`;
    card.type="button";

    const img=document.createElement("img");
    img.src=stand.image;
    img.alt=stand.name;
    img.loading="lazy";

    const overlay=document.createElement("span");
    overlay.className="card-overlay";
    overlay.textContent=stand.name;

    card.append(img,overlay);
    card.addEventListener("click",()=>openStand(stand));
    return card;
}

function openStand(stand){
    modalName.textContent=stand.name;
    modalRarity.textContent=stand.rarity;
    modalRarity.className=`rarity-pill rarity-${stand.rarity.toLowerCase()}`;
    modalDescription.textContent=stand.description||"No description provided on the Trello card.";
    modalImage.src=stand.image;
    modalImage.alt=stand.name;
    modal.showModal();
}

for(const rarity of rarityOrder){
    const section=document.createElement("section");
    section.className=`tier-row rarity-${rarity.toLowerCase()}`;

    const label=document.createElement("div");
    label.className="tier-label";
    label.innerHTML=`<span>${rarity}</span><small>${stands.filter(s=>s.rarity===rarity).length} stands</small>`;

    const grid=document.createElement("div");
    grid.className="stand-grid";

    for(const stand of stands){
        if(stand.rarity===rarity) grid.appendChild(createCard(stand));
    }

    section.append(label,grid);
    board.appendChild(section);
}

closeModal.addEventListener("click",()=>modal.close());
modal.addEventListener("click",event=>{if(event.target===modal) modal.close();});
